345	bool TGAHandler::canRead() const
346	{
347	    if (canRead(device())) {
348	        setFormat("tga");
349	        return true;
350	    }
351	    return false;
352	}
353	
354	bool TGAHandler::read(QImage *outImage)
355	{
356	    //qDebug() << "Loading TGA file!";
357	
358	    QDataStream s(device());
359	    s.setByteOrder(QDataStream::LittleEndian);
360	
361	    // Read image header.
362	    TgaHeader tga;
363	    s >> tga;
364	    s.device()->seek(TgaHeader::SIZE + tga.id_length);
365	
366	    // Check image file format.
367	    if (s.atEnd()) {
368	//         qDebug() << "This TGA file is not valid.";
369	        return false;
370	    }
371	
372	    // Check supported file types.
373	    if (!IsSupported(tga)) {
374	//         qDebug() << "This TGA file is not supported.";
375	        return false;
376	    }
377	
378	    QImage img;
379	    bool result = LoadTGA(s, tga, img);
380	
381	    if (result == false) {
382	//         qDebug() << "Error loading TGA file.";
383	        return false;
384	    }
385	
386	    *outImage = img;
387	    return true;
388	}
389	
390	bool TGAHandler::write(const QImage &image)
391	{
392	    QDataStream s(device());
393	    s.setByteOrder(QDataStream::LittleEndian);
394	
395	    const QImage &img = image;
396	    const bool hasAlpha = (img.format() == QImage::Format_ARGB32);
397	    for (int i = 0; i < 12; i++) {
398	        s << targaMagic[i];
399	    }
400	
401	    // write header
402	    s << quint16(img.width());   // width
403	    s << quint16(img.height());   // height
404	    s << quint8(hasAlpha ? 32 : 24);   // depth (24 bit RGB + 8 bit alpha)
405	    s << quint8(hasAlpha ? 0x24 : 0x20);   // top left image (0x20) + 8 bit alpha (0x4)
406	
407	    for (int y = 0; y < img.height(); y++)
408	        for (int x = 0; x < img.width(); x++) {
409	            const QRgb color = img.pixel(x, y);
410	            s << quint8(qBlue(color));
411	            s << quint8(qGreen(color));
412	            s << quint8(qRed(color));
413	            if (hasAlpha) {
414	                s << quint8(qAlpha(color));
415	            }
416	        }
417	
418	    return true;
419	}
420	
421	bool TGAHandler::canRead(QIODevice *device)
422	{
423	    if (!device) {
424	        qWarning("TGAHandler::canRead() called with no device");
425	        return false;
426	    }
427	
428	    qint64 oldPos = device->pos();
429	    QByteArray head = device->read(TgaHeader::SIZE);
430	    int readBytes = head.size();
431	
432	    if (device->isSequential()) {
433	        for (int pos = readBytes - 1; pos >= 0; --pos) {
434	            device->ungetChar(head[pos]);
435	        }
436	    } else {
437	        device->seek(oldPos);
438	    }
439	
440	    if (readBytes < TgaHeader::SIZE) {
441	        return false;
442	    }
443	
444	    QDataStream stream(head);
445	    stream.setByteOrder(QDataStream::LittleEndian);
446	    TgaHeader tga;
447	    stream >> tga;
448	    return IsSupported(tga);
449	}
450	
451	QImageIOPlugin::Capabilities TGAPlugin::capabilities(QIODevice *device, const QByteArray &format) const
452	{
453	    if (format == "tga") {
454	        return Capabilities(CanRead | CanWrite);
455	    }
456	    if (!format.isEmpty()) {
457	        return {};
458	    }
459	    if (!device->isOpen()) {
460	        return {};
461	    }
462	
463	    Capabilities cap;
464	    if (device->isReadable() && TGAHandler::canRead(device)) {
465	        cap |= CanRead;
466	    }
467	    if (device->isWritable()) {
468	        cap |= CanWrite;
469	    }
470	    return cap;
471	}
472	
473	QImageIOHandler *TGAPlugin::create(QIODevice *device, const QByteArray &format) const
474	{
475	    QImageIOHandler *handler = new TGAHandler;
476	    handler->setDevice(device);
477	    handler->setFormat(format);
478	    return handler;
479	}
